import json, re, tiktoken

ENC = tiktoken.get_encoding("o200k_base")
COLS = ["file", "lineStart", "lineEnd", "nodeKind", "parent", "symbolSignature", "snippet", "rank", "finalScore"]


def tok(s):
    return len(ENC.encode(s, disallowed_special=()))


def split_cells(line):
    cells, cur, inq, i = [], [], False, 0
    while i < len(line):
        c = line[i]
        if inq:
            cur.append(c)
            if c == "\\":
                cur.append(line[i + 1]); i += 1
            elif c == '"':
                inq = False
        else:
            if c == '"':
                inq = True; cur.append(c)
            elif c == ",":
                cells.append("".join(cur)); cur = []
            else:
                cur.append(c)
        i += 1
    cells.append("".join(cur))
    return cells


def unq(c):
    if c.startswith('"') and c.endswith('"') and len(c) >= 2:
        return re.sub(r'\\(.)', lambda m: {"n": "\n", "t": "\t", "r": "\r"}.get(m.group(1), m.group(1)), c[1:-1])
    return c


def parse(out):
    lines = out.split("\n")
    header = lines[0]
    m = re.match(r"^search\[(\d+)\]\{([^}]*)\}:$", header)
    cols = m.group(2).split(",") if m else None
    rows, tail = [], []
    for ln in lines[1:]:
        if ln.startswith("  ") and m and len(rows) < int(m.group(1)):
            cells = split_cells(ln[2:])
            assert len(cells) == len(cols), (ln, cols)
            rows.append(dict(zip(cols, cells)))
        elif ln != "":
            tail.append(ln)
    return header, cols, rows, tail


def load():
    data = json.load(open("/tmp/claude-501/ec/data.json"))
    for d in data:
        d["header"], d["cols"], d["rows"], d["tail"] = parse(d["stdout"])
    return data

